<?php
require_once __DIR__ . '/../helpers.php'; require_once __DIR__ . '/../config/database.php'; require_login();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$product=(int)($_POST['product_id']??0);$type=$_POST['type']??'';$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$note=trim((string)($_POST['note']??''));try{if($product<1||!in_array($type,['in','out'],true)||$qty===false||$qty<1)throw new RuntimeException('Produk, jenis transaksi, dan jumlah minimal 1 wajib valid.');$pdo->beginTransaction();$s=$pdo->prepare('SELECT quantity FROM products WHERE id=? FOR UPDATE');$s->execute([$product]);$p=$s->fetch();if(!$p)throw new RuntimeException('Produk tidak ditemukan.');$new=(int)$p['quantity']+($type==='in'?$qty:-$qty);if($new<0)throw new RuntimeException('Stok tidak cukup. Barang keluar tidak boleh membuat stok negatif.');$s=$pdo->prepare('UPDATE products SET quantity=? WHERE id=?');$s->execute([$new,$product]);$s=$pdo->prepare('INSERT INTO stock_transactions(product_id,user_id,type,quantity,note) VALUES(?,?,?,?,?)');$s->execute([$product,current_user()['id'],$type,$qty,$note?:null]);$pdo->commit();flash('Transaksi berhasil disimpan dan stok diperbarui.');redirect('stock.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'Transaksi gagal disimpan. Periksa data dan coba lagi.':$e->getMessage();}}
$products=$pdo->query('SELECT id,sku,name,quantity FROM products ORDER BY name')->fetchAll();
layout_start('Transaksi Stok');if($error)echo '<div class="alert error">'.e($error).'</div>';
echo '<div class="card"><p>Catat barang masuk atau keluar. Perubahan stok dan riwayat disimpan dalam satu transaksi database.</p><form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><label>Produk</label><select name="product_id" required><option value="">Pilih produk</option>';foreach($products as $p)echo '<option value="'.(int)$p['id'].'">'.e($p['sku'].' — '.$p['name'].' (stok: '.$p['quantity'].')').'</option>';echo '</select><label>Jenis transaksi</label><select name="type" required><option value="in">Barang masuk</option><option value="out">Barang keluar</option></select><label>Jumlah</label><input type="number" name="quantity" min="1" step="1" required><label>Catatan</label><input name="note" maxlength="255" placeholder="Contoh: pembelian / penjualan"><p><button>Simpan Transaksi</button></p></form></div>';layout_end();
